{
  "criteria": [
    { "id": "task-response", "score": 60, "max": 60, "comment": "Clear, on-task answer: «Я сейчас живу в Колорадо» gives exactly the place asked for. The extra detail about the fiancée is natural and relevant." },
    { "id": "completeness", "score": 20, "max": 20, "comment": "A full sentence with subject, verb and place, plus a second short sentence («она украинка»). This is more than the task requires." },
    { "id": "grammar", "score": 16, "max": 20, "comment": "«живу в Колорадо» is correct (Колорадо does not decline), and «она украинка» is fine. The one real slip is «с моя невеста»: after «с» meaning 'with', you need the instrumental «с моей невестой». Both transcripts agree on this, and it does not obscure the meaning." }
  ],
  "corrected": "Я сейчас живу в Колорадо с моей невестой. Она украинка.",
  "changes": [
    { "before": "с моя невеста", "after": "с моей невестой", "explanation": "The preposition «с» ('with') takes the instrumental case. Feminine «моя невеста» becomes «моей невестой»." }
  ],
  "tips": [
    "Learn the instrumental after «с» ('with') as a fixed pattern: «с мамой», «с другом», «с моей невестой».",
    "Keep answering like this: a full sentence plus one short extra fact makes a strong A1 reply.",
    "Remember that foreign names ending in -о, such as «Колорадо», «Торонто» and «Чикаго», never change their form: «в Колорадо», «из Колорадо»."
  ]
}
